-- Existing SYSTEM test schema subset for isolated direct-writer transaction checks.
CREATE TABLE IF NOT EXISTS "system_users" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "username" varchar(30) NOT NULL,
    "employee_no" varchar(50),
    "custom_info" varchar,
    "password" varchar(100) NOT NULL DEFAULT '',
    "nickname" varchar(30) NOT NULL,
    "remark" varchar(500),
    "dept_id" bigint,
    "post_ids" varchar(255),
    "email" varchar(50) DEFAULT '',
    "mobile" varchar(11) DEFAULT '',
    "sex" tinyint DEFAULT 0,
    "avatar" varchar(512) DEFAULT '',
    "status" tinyint NOT NULL,
    "login_ip" varchar(50) DEFAULT '',
    "login_date" timestamp,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '用户表';
CREATE TABLE IF NOT EXISTS "system_dept" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64),
    "name" varchar(30) NOT NULL DEFAULT '',
    "parent_id" bigint NOT NULL DEFAULT 0,
    "sort" int NOT NULL DEFAULT 0,
    "leader_user_id" bigint,
    "phone" varchar(11),
    "email" varchar(50),
    "status" tinyint NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '部门表';
CREATE TABLE IF NOT EXISTS "system_company" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "code" varchar(64) NOT NULL,
    "name" varchar(128) NOT NULL,
    "status" tinyint NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '公司主数据';
CREATE TABLE IF NOT EXISTS "system_user_company_department_scope" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "user_id" bigint NOT NULL,
    "company_id" bigint NOT NULL,
    "company_code" varchar(64) NOT NULL,
    "company_name" varchar(128) NOT NULL,
    "department_id" bigint,
    "department_code" varchar(64),
    "department_name" varchar(128),
    "scope_role" varchar(32) NOT NULL,
    "is_primary" bit NOT NULL DEFAULT FALSE,
    "effective_from" timestamp NOT NULL,
    "effective_to" timestamp,
    "status" tinyint NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CHECK (("department_id" IS NULL AND "department_code" IS NULL)
        OR ("department_id" IS NOT NULL AND "department_code" IS NOT NULL))
) COMMENT '用户公司部门有效范围';
CREATE TABLE IF NOT EXISTS "system_post" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code" varchar(64) NOT NULL,
    "name" varchar(50) NOT NULL,
    "sort" int NOT NULL,
    "status" tinyint NOT NULL,
    "remark" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '岗位表';
CREATE TABLE IF NOT EXISTS "system_role" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(30) NOT NULL,
    "code" varchar(100) NOT NULL,
    "sort" int NOT NULL,
    "data_scope" tinyint NOT NULL DEFAULT 1,
    "data_scope_dept_ids" varchar(500) NOT NULL DEFAULT '',
    "status" tinyint NOT NULL,
    "type" tinyint NOT NULL,
    "remark" varchar(500),
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '角色表';
CREATE TABLE IF NOT EXISTS "system_user_role" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "role_id" bigint NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '用户角色关联表';
CREATE TABLE IF NOT EXISTS "system_role_menu" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "role_id" bigint NOT NULL,
    "menu_id" bigint NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '角色菜单关联表';
CREATE TABLE IF NOT EXISTS "system_user_post" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL DEFAULT 0,
    "post_id" bigint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '用户岗位关联表';
CREATE TABLE system_tenant(id BIGINT PRIMARY KEY,account_count INT,deleted BOOLEAN DEFAULT FALSE);
